"""In-memory table.

Secret: how rows and the column schema are stored.  Callers see only
column names/types and read-only records.
"""


class Record:
    """Read-only view of one row."""

    __slots__ = ("_index", "_values")

    def __init__(self, index, values):
        self._index = index
        self._values = values

    def get(self, name):
        return self._values[self._index[name]]


class Dataset:
    def __init__(self, names, types, rows):
        self._names = list(names)
        self._types = list(types)
        self._index = {n: i for i, n in enumerate(self._names)}
        self._rows = rows

    @classmethod
    def from_rows(cls, names, types, rows):
        """Build from column names, their types and value sequences in that order."""
        return cls(names, types, [list(r) for r in rows])

    def has(self, name):
        return name in self._index

    def type_of(self, name):
        return self._types[self._index[name]]

    def __len__(self):
        return len(self._rows)

    def records(self):
        index = self._index
        for row in self._rows:
            yield Record(index, row)

    def filter(self, predicate):
        """New dataset holding the rows for which predicate(record) is True."""
        index = self._index
        kept = [row for row in self._rows if predicate(Record(index, row))]
        return Dataset(self._names, self._types, kept)

    def derive(self, name, value_type, compute):
        """New dataset with column `name` (added or replaced) = compute(record)."""
        index = self._index
        values = [compute(Record(index, row)) for row in self._rows]
        names = list(self._names)
        types = list(self._types)
        if name in index:
            pos = index[name]
            types[pos] = value_type
            rows = []
            for row, value in zip(self._rows, values):
                row = list(row)
                row[pos] = value
                rows.append(row)
        else:
            names.append(name)
            types.append(value_type)
            rows = [row + [value] for row, value in zip(self._rows, values)]
        return Dataset(names, types, rows)
"""JSON rendering.

Secret: the JSON document shape, row ordering, object key ordering and how
values (numbers, timestamps, nulls) are encoded.
"""

import json
import math
from collections import OrderedDict

from . import timestamps
from . import valuetypes as T
from .errors import ExecutionError


def _sort_key(value):
    # Nulls sort first; values within one column share a type, so Python's
    # ordering gives numeric, code-point and chronological order respectively.
    return (0, 0) if value is None else (1, value)


def _encode(value, value_type=None):
    if value is None:
        return None
    if value_type is not None and T.is_timestamp(value_type):
        return timestamps.format_utc(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ExecutionError("cannot emit non-finite number")
        return value + 0.0
    return value


def _object(result, row):
    obj = OrderedDict()
    if result.windowed:
        obj["window_start"] = timestamps.format_utc(row.window_start)
        obj["window_end"] = timestamps.format_utc(row.window_end)
    for name, value_type, value in zip(result.group_columns, result.group_types, row.keys):
        obj[name] = _encode(value, value_type)
    for alias in sorted(result.aliases):
        obj[alias] = _encode(row.values[alias])
    return obj


def render(result):
    """Serialise a ResultSet to the deterministic JSON text."""
    if result.scalar:
        document = _object(result, result.rows[0])
    else:
        rows = sorted(result.rows, key=lambda r: (
            _sort_key(r.window_start), tuple(_sort_key(k) for k in r.keys)))
        document = [_object(result, r) for r in rows]
    try:
        return json.dumps(document, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
    except ValueError as exc:
        raise ExecutionError("cannot emit result: %s" % exc)
"""Timestamps.

Secret: how timestamp text is parsed (ISO 8601 or an explicit strptime
format, with a default zone for naive values) and how instants are
represented and rendered.  Callers may rely only on the functions below and
